### How do you collect to an unmodifiable list?

```java
package com.bank.service;

import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

public class UnmodifiableCollectDemo {
    record Account(String id, BigDecimal balance) {}

    public static void main(String[] args) {
        List<Account> accounts = List.of(
            new Account("SAV2001", new BigDecimal("50000")),
            new Account("SAV2002", new BigDecimal("150000")),
            new Account("SAV2003", new BigDecimal("75000"))
        );

        // Java 10: toUnmodifiableList
        List<Account> unmod = accounts.stream()
            .filter(a -> a.balance().compareTo(new BigDecimal("60000")) > 0)
            .collect(Collectors.toUnmodifiableList());

        // Java 16: Stream.toList()
        List<Account> toList = accounts.stream()
            .filter(a -> a.balance().compareTo(new BigDecimal("60000")) > 0)
            .toList();

        // Java 8+: collectingAndThen
        List<Account> wrapped = accounts.stream()
            .filter(a -> a.balance().compareTo(new BigDecimal("60000")) > 0)
            .collect(Collectors.collectingAndThen(
                Collectors.toList(),
                Collections::unmodifiableList));

        // All three throw UnsupportedOperationException on mutation
        try {
            unmod.add(new Account("SAV9999", BigDecimal.ZERO));
        } catch (UnsupportedOperationException e) {
            System.out.println("Cannot modify: " + e.getClass().getSimpleName());
        }
    }
}
```

